-- =====================================================================
-- 01_schema.sql : 장학·졸업 요건 진단 시스템 테이블 (Oracle 12c 이상)  schema v4
--
--   MySQL 판(db/01_schema.sql)과 테이블·칼럼 이름이 같다. Oracle 로 옮기며 바뀐 점:
--     AUTO_INCREMENT        → GENERATED BY DEFAULT ON NULL AS IDENTITY
--     BOOLEAN               → NUMBER(1) + CHECK (0, 1)
--     ENUM                  → VARCHAR2 + CHECK IN (...)
--     저장 생성 칼럼        → 가상 칼럼(VIRTUAL). 인덱스·UNIQUE 를 걸 수 있는 것은 같다
--     ON UPDATE CASCADE     → Oracle 에 없음 (과목군 코드는 화면에서 바꾸지 않으므로 영향 없음)
--     DATETIME              → DATE
--     문자 길이             → VARCHAR2(n CHAR) : 한글 1자 = 1칸으로 센다 (BYTE 기준이면 한글은 3칸)
--     DB 이름(grad_check)   → 팀 Oracle 계정(스키마) 안에 바로 만든다
--
--   테이블 14개
--     핵심 (원래 ERD)  DEPARTMENT, STUDENT, COURSE, ENROLLMENT, GRAD_REQ, SCHOLARSHIP
--     코드             AREA(이수구분), GRADE_SCALE(등급→평점)
--     요건 상세        GRAD_REQ_AREA, COURSE_GROUP, COURSE_GROUP_MEMBER, GRAD_REQ_GROUP
--     집계             SEMESTER_RECORD (트리거가 관리하는 학기별 평점, FR-05)
--     로그인           USER_ACCOUNT
-- =====================================================================

CREATE OR REPLACE FUNCTION fn_schema_version RETURN NUMBER DETERMINISTIC IS
BEGIN
    RETURN 4;
END;
/

-- ---------------------------------------------------------------- 코드
-- 이수구분. parent_code 로 묶음 영역을 만든다 (예: 전공 = 전공필수 + 전공선택).
CREATE TABLE AREA (
    area_code    CHAR(2)            NOT NULL,
    area_name    VARCHAR2(20 CHAR)  NOT NULL,
    parent_code  CHAR(2),
    sort_order   NUMBER(3)          DEFAULT 0 NOT NULL,
    CONSTRAINT pk_area PRIMARY KEY (area_code),
    CONSTRAINT fk_area_parent FOREIGN KEY (parent_code) REFERENCES AREA (area_code)
);

CREATE TABLE GRADE_SCALE (
    grade         VARCHAR2(2)   NOT NULL,
    grade_point   NUMBER(2,1),                -- P/NP 는 평점 없음
    earns_credit  NUMBER(1)     NOT NULL,     -- 학점 인정 여부 (F, NP 는 0)
    in_gpa        NUMBER(1)     NOT NULL,     -- 평점 계산 포함 여부 (P, NP 는 0)
    CONSTRAINT pk_grade_scale PRIMARY KEY (grade),
    CONSTRAINT ck_grade_point CHECK (grade_point IS NULL OR grade_point BETWEEN 0 AND 4.5),
    CONSTRAINT ck_gs_earns CHECK (earns_credit IN (0, 1)),
    CONSTRAINT ck_gs_in_gpa CHECK (in_gpa IN (0, 1))
);

-- ---------------------------------------------------------------- 기본
CREATE TABLE DEPARTMENT (
    dept_id    VARCHAR2(10)        NOT NULL,
    dept_name  VARCHAR2(50 CHAR)   NOT NULL,
    campus     VARCHAR2(10 CHAR)   NOT NULL,
    homepage   VARCHAR2(200),
    CONSTRAINT pk_department PRIMARY KEY (dept_id),
    CONSTRAINT uq_dept_name UNIQUE (dept_name)
);

CREATE TABLE STUDENT (
    student_id       CHAR(8)            NOT NULL,
    name             VARCHAR2(30 CHAR)  NOT NULL,
    dept_id          VARCHAR2(10)       NOT NULL,
    admission_year   NUMBER(4)          NOT NULL,
    grade_level      NUMBER(1)          NOT NULL,           -- 현재 학년 (봉사시간 예외 판정)
    income_bracket   NUMBER(2)          NOT NULL,
    volunteer_hours  NUMBER(4)          DEFAULT 0 NOT NULL, -- 직전 학기까지 인정 봉사시간
    CONSTRAINT pk_student PRIMARY KEY (student_id),
    CONSTRAINT fk_student_dept FOREIGN KEY (dept_id) REFERENCES DEPARTMENT (dept_id),
    CONSTRAINT ck_income    CHECK (income_bracket BETWEEN 0 AND 10),
    CONSTRAINT ck_level     CHECK (grade_level BETWEEN 1 AND 5),
    CONSTRAINT ck_volunteer CHECK (volunteer_hours >= 0)
);
-- 학과별 학생 목록과 "학생 → 적용 졸업요건(입학연도 구간)" 조인에 쓰는 인덱스
CREATE INDEX idx_student_dept_year ON STUDENT (dept_id, admission_year);

-- course_id 는 홍익대 학수번호(6자리). 성적 가져오기로 새로 등록된 과목은 U 로 시작한다.
CREATE TABLE COURSE (
    course_id       VARCHAR2(10)       NOT NULL,
    course_name     VARCHAR2(60 CHAR)  NOT NULL,
    credits         NUMBER(1)          NOT NULL,
    design_credits  NUMBER(1)          DEFAULT 0 NOT NULL,   -- 공학인증 설계학점
    area_code       CHAR(2)            NOT NULL,
    dept_id         VARCHAR2(10),                            -- 교양·MSC 는 NULL
    CONSTRAINT pk_course PRIMARY KEY (course_id),
    CONSTRAINT fk_course_area FOREIGN KEY (area_code) REFERENCES AREA (area_code),
    CONSTRAINT fk_course_dept FOREIGN KEY (dept_id)  REFERENCES DEPARTMENT (dept_id),
    CONSTRAINT ck_credits CHECK (credits BETWEEN 0 AND 6),
    CONSTRAINT ck_design  CHECK (design_credits BETWEEN 0 AND credits)
);
CREATE INDEX idx_course_area ON COURSE (area_code);

-- term: 1 = 1학기, 2 = 2학기, 3 = 여름 계절학기, 4 = 겨울 계절학기
-- sem_order: 학기를 시간 순서로 정렬하는 값 (2025년 1학기=20251, 여름=20252, 2학기=20253, 겨울=20254).
--            year·term 에서 계산되는 가상 칼럼이라 따로 고칠 일이 없고(갱신 이상 없음),
--            인덱스를 걸 수 있어 "재수강 중 가장 최근 성적"을 인덱스만으로 찾는다.
CREATE TABLE ENROLLMENT (
    enroll_id   NUMBER(10)    GENERATED BY DEFAULT ON NULL AS IDENTITY,
    student_id  CHAR(8)       NOT NULL,
    course_id   VARCHAR2(10)  NOT NULL,
    year        NUMBER(4)     NOT NULL,
    term        NUMBER(1)     NOT NULL,
    grade       VARCHAR2(2)   NOT NULL,
    sem_order   NUMBER(6)     GENERATED ALWAYS AS
                (year * 10 + CASE term WHEN 1 THEN 1 WHEN 3 THEN 2 WHEN 2 THEN 3 ELSE 4 END) VIRTUAL,
    CONSTRAINT pk_enrollment PRIMARY KEY (enroll_id),
    -- 같은 학생이 같은 학기에 같은 과목을 두 번 들을 수 없다 + 재수강 최신 성적 조회용
    CONSTRAINT uq_enroll UNIQUE (student_id, course_id, sem_order),
    CONSTRAINT fk_enr_student FOREIGN KEY (student_id) REFERENCES STUDENT (student_id) ON DELETE CASCADE,
    CONSTRAINT fk_enr_course  FOREIGN KEY (course_id)  REFERENCES COURSE (course_id),
    CONSTRAINT fk_enr_grade   FOREIGN KEY (grade)      REFERENCES GRADE_SCALE (grade),
    CONSTRAINT ck_term CHECK (term BETWEEN 1 AND 4),
    CONSTRAINT ck_year CHECK (year BETWEEN 1990 AND 2100)
);
-- 학기 단위 재계산(트리거)과 학기별 성적 조회용
CREATE INDEX idx_enroll_term ON ENROLLMENT (student_id, year, term);
CREATE INDEX idx_enroll_course ON ENROLLMENT (course_id);

-- ---------------------------------------------------------------- 기준
-- 졸업요건은 학과 + 입학연도 "구간" 단위 (예: 2019~2021학번, 2022학번~).
-- to_year 가 NULL 이면 그 이후 입학생 전체. 구간이 겹치지 않는지는 트리거가 검사한다.
CREATE TABLE GRAD_REQ (
    req_id              NUMBER(10)          GENERATED BY DEFAULT ON NULL AS IDENTITY,
    dept_id             VARCHAR2(10)        NOT NULL,
    from_year           NUMBER(4)           NOT NULL,
    to_year             NUMBER(4),
    total_credits       NUMBER(3)           NOT NULL,
    min_gpa             NUMBER(3,2),                       -- NULL 이면 평점 기준 없음
    min_design_credits  NUMBER(3)           DEFAULT 0 NOT NULL,
    note                VARCHAR2(500 CHAR),                -- 시스템이 판정하지 않는 요건 안내 (영어 성적 등)
    source_url          VARCHAR2(300),
    CONSTRAINT pk_grad_req PRIMARY KEY (req_id),
    CONSTRAINT fk_gradreq_dept FOREIGN KEY (dept_id) REFERENCES DEPARTMENT (dept_id),
    CONSTRAINT ck_gradreq_years CHECK (to_year IS NULL OR to_year >= from_year),
    CONSTRAINT ck_gradreq_total CHECK (total_credits > 0),
    CONSTRAINT ck_gradreq_gpa   CHECK (min_gpa IS NULL OR min_gpa BETWEEN 0 AND 4.5)
);
CREATE INDEX idx_gradreq_dept_year ON GRAD_REQ (dept_id, from_year);

CREATE TABLE GRAD_REQ_AREA (
    req_id       NUMBER(10)  NOT NULL,
    area_code    CHAR(2)     NOT NULL,
    min_credits  NUMBER(3)   NOT NULL,
    CONSTRAINT pk_grad_req_area PRIMARY KEY (req_id, area_code),
    CONSTRAINT fk_gra_req  FOREIGN KEY (req_id)    REFERENCES GRAD_REQ (req_id) ON DELETE CASCADE,
    CONSTRAINT fk_gra_area FOREIGN KEY (area_code) REFERENCES AREA (area_code),
    CONSTRAINT ck_gra_min  CHECK (min_credits >= 0)
);

-- 과목군: 졸업요건에 쓰이는 과목 묶음. 규칙(rule_type)이 두 가지다.
--   CREDITS : 이 과목들 중에서 n학점 이상 (택1 글쓰기, SW/데이터활용역량 모듈 등). n 은 GRAD_REQ_GROUP 에
--   ALL     : 이 과목들을 모두 이수 (전공필수·인증필수)
-- dept_id 가 NULL 이면 여러 학과가 같이 쓰는 공통 과목군, 아니면 그 학과 담당자만 고칠 수 있다.
CREATE TABLE COURSE_GROUP (
    group_code   VARCHAR2(20)        NOT NULL,
    group_name   VARCHAR2(50 CHAR)   NOT NULL,
    rule_type    VARCHAR2(7)         DEFAULT 'CREDITS' NOT NULL,
    dept_id      VARCHAR2(10),
    description  VARCHAR2(300 CHAR),
    CONSTRAINT pk_course_group PRIMARY KEY (group_code),
    CONSTRAINT fk_cg_dept FOREIGN KEY (dept_id) REFERENCES DEPARTMENT (dept_id),
    CONSTRAINT ck_cg_rule CHECK (rule_type IN ('CREDITS', 'ALL'))
);

CREATE TABLE COURSE_GROUP_MEMBER (
    group_code  VARCHAR2(20)  NOT NULL,
    course_id   VARCHAR2(10)  NOT NULL,
    CONSTRAINT pk_course_group_member PRIMARY KEY (group_code, course_id),
    CONSTRAINT fk_cgm_group  FOREIGN KEY (group_code) REFERENCES COURSE_GROUP (group_code) ON DELETE CASCADE,
    CONSTRAINT fk_cgm_course FOREIGN KEY (course_id)  REFERENCES COURSE (course_id)
);
CREATE INDEX idx_cgm_course ON COURSE_GROUP_MEMBER (course_id);

-- 요건 ↔ 과목군. min_credits 는 CREDITS 과목군에서만 쓰고, ALL 과목군은 NULL.
CREATE TABLE GRAD_REQ_GROUP (
    req_id       NUMBER(10)    NOT NULL,
    group_code   VARCHAR2(20)  NOT NULL,
    min_credits  NUMBER(3),
    CONSTRAINT pk_grad_req_group PRIMARY KEY (req_id, group_code),
    CONSTRAINT fk_grg_req   FOREIGN KEY (req_id)     REFERENCES GRAD_REQ (req_id) ON DELETE CASCADE,
    CONSTRAINT fk_grg_group FOREIGN KEY (group_code) REFERENCES COURSE_GROUP (group_code) ON DELETE CASCADE,
    CONSTRAINT ck_grg_min CHECK (min_credits IS NULL OR min_credits > 0)
);
CREATE INDEX idx_grg_group ON GRAD_REQ_GROUP (group_code);

CREATE TABLE SCHOLARSHIP (
    sch_id                  NUMBER(10)         GENERATED BY DEFAULT ON NULL AS IDENTITY,
    sch_name                VARCHAR2(50 CHAR)  NOT NULL,
    category                VARCHAR2(10 CHAR)  DEFAULT '성적우수' NOT NULL,
    amount_desc             VARCHAR2(30 CHAR),            -- 등록금 전액, 80%, 90만원 ...
    min_gpa                 NUMBER(3,2)        NOT NULL,
    min_credits             NUMBER(3)          NOT NULL,  -- 직전 학기 취득 학점 기준
    max_income              NUMBER(2),                    -- NULL 이면 소득 무관
    min_volunteer_hours     NUMBER(4),                    -- NULL 이면 봉사 조건 없음
    volunteer_exempt_level  NUMBER(1),                    -- 이 학년 이상은 봉사 조건 면제 (예: 4)
    dept_id                 VARCHAR2(10),                 -- NULL 이면 전체 학과 대상
    source_url              VARCHAR2(300),
    CONSTRAINT pk_scholarship PRIMARY KEY (sch_id),
    CONSTRAINT fk_sch_dept FOREIGN KEY (dept_id) REFERENCES DEPARTMENT (dept_id),
    CONSTRAINT ck_sch_category CHECK (category IN ('성적우수', '가계지원', '학과')),
    CONSTRAINT ck_sch_gpa    CHECK (min_gpa BETWEEN 0 AND 4.5),
    CONSTRAINT ck_sch_income CHECK (max_income IS NULL OR max_income BETWEEN 0 AND 10)
);

-- ---------------------------------------------------------------- 집계
-- ENROLLMENT 에서 계산되는 값을 저장해 두는 표. ENROLLMENT·COURSE 트리거만 이 표를 고친다 (03_triggers.sql).
-- 장학 판정의 "직전 학기 평점"을 학생마다 매번 다시 계산하지 않으려고 둔다.
CREATE TABLE SEMESTER_RECORD (
    student_id         CHAR(8)      NOT NULL,
    year               NUMBER(4)    NOT NULL,
    term               NUMBER(1)    NOT NULL,
    attempted_credits  NUMBER(3)    NOT NULL,   -- 신청 학점 (P/NP 포함)
    earned_credits     NUMBER(3)    NOT NULL,   -- 취득 학점 (F, NP 제외)
    gpa                NUMBER(3,2),             -- 평점 대상 과목이 없으면 NULL
    sem_order          NUMBER(6)    GENERATED ALWAYS AS
                       (year * 10 + CASE term WHEN 1 THEN 1 WHEN 3 THEN 2 WHEN 2 THEN 3 ELSE 4 END) VIRTUAL,
    CONSTRAINT pk_semester_record PRIMARY KEY (student_id, year, term),
    CONSTRAINT fk_sr_student FOREIGN KEY (student_id) REFERENCES STUDENT (student_id) ON DELETE CASCADE
);
CREATE INDEX idx_sr_order ON SEMESTER_RECORD (student_id, sem_order);

-- ---------------------------------------------------------------- 로그인
CREATE TABLE USER_ACCOUNT (
    login_id       VARCHAR2(20)   NOT NULL,
    password_hash  VARCHAR2(255)  NOT NULL,     -- PHP password_hash() (bcrypt)
    role           VARCHAR2(7)    NOT NULL,
    student_id     CHAR(8),
    dept_id        VARCHAR2(10),
    last_login     DATE,
    CONSTRAINT pk_user_account PRIMARY KEY (login_id),
    CONSTRAINT uq_ua_student UNIQUE (student_id),       -- 학생 한 명에 계정 하나
    CONSTRAINT fk_ua_student FOREIGN KEY (student_id) REFERENCES STUDENT (student_id) ON DELETE CASCADE,
    CONSTRAINT fk_ua_dept    FOREIGN KEY (dept_id)    REFERENCES DEPARTMENT (dept_id),
    CONSTRAINT ck_ua_role CHECK (
        (role = 'student' AND student_id IS NOT NULL AND dept_id IS NULL) OR
        (role = 'admin'   AND dept_id    IS NOT NULL AND student_id IS NULL)
    )
);
